 async function me(){const [d,options]=await Promise.all([api('me'),api('login/options')]);setUser(d.user);setTrackingReady(true);setEmailReady(d.emailReady);setTeacherPasswordReady(options.teacherPasswordReady);return d.user;}
 useEffect(()=>{me().then(u=>{const q=new URLSearchParams(location.search);if(u?.role==='student'&&!q.has('lesson'))setArea(true);else if(q.has('area')){if(u)setArea(true);else setModal(q.get('area')==='teacher'?'teacher':'login');}}).catch(()=>{});},[]);
