function Students({students,refresh,report,group}:{group:Group;students:Student[];refresh:()=>Promise<void>;report:(s:string)=>void}){
 const [busy,setBusy]=useState(false),[error,setError]=useState(''),[edit,setEdit]=useState<Student|null>(null),[access,setAccess]=useState<{name:string;username:string;password:string;email:string}|null>(null),[copied,setCopied]=useState(false);
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();const form=e.currentTarget,f=new FormData(form);setBusy(true);setError('');try{const data={name:String(f.get('name')),email:String(f.get('email')||''),username:String(f.get('username')),password:String(f.get('password')||''),student_group:group};await api(edit?'students/'+edit.id:'students',edit?'PATCH':'POST',data);if(data.password){setAccess({...data,username:data.username.normalize('NFKC').toLowerCase().trim()});setCopied(false);}setEdit(null);form.reset();await refresh();report('Prisijungimas išsaugotas.');}catch(e:any){setError(e.message);}finally{setBusy(false);}}
 const accessText=access?`Labas, ${access.name}!\n\nPrisijungimo vardas: ${access.username}\nSlaptažodis: ${access.password}\n\n${typeof window!=='undefined'?window.location.origin:'https://matematikabestreso.lt'}/?area=student`:'';
 return <div className="students-layout"><section className="glass panel"><h2>{edit?'Mokinio duomenys':'Naujas mokinys'}</h2><form key={edit?.id||'new'} onSubmit={submit}><label>Vardas, pavardė<input name="name" required maxLength={80} defaultValue={edit?.name||''}/></label><label>El. paštas<input name="email" type="email" required={group==='remote'} maxLength={254} defaultValue={edit?.email||''}/></label><label>Prisijungimo vardas<input name="username" required minLength={3} maxLength={32} defaultValue={edit?.username||''} autoComplete="off" autoCapitalize="none" spellCheck={false}/></label><label>{edit?.username?'Naujas slaptažodis':'Slaptažodis'}<input name="password" type="password" required={!edit?.username} minLength={8} maxLength={128} autoComplete="new-password"/></label><p className="hint">{edit?.username?'Palik slaptažodį tuščią, jei jo nekeiti.':'Slaptažodis – bent 8 simboliai.'}</p>{error&&<p className="error" role="alert">{error}</p>}<button className="button primary full" disabled={busy}>{busy?<Loader2 className="spin" size={18}/>:<Check size={18}/>}Išsaugoti</button>{edit&&<button type="button" className="button subtle full" onClick={()=>setEdit(null)}>Atšaukti</button>}</form></section>
 <section className="glass panel"><h2>{group==='remote'?'Nuotolinė pagalba':'Mano mokiniai'}</h2>{!students.length?<p className="muted">Mokinių dar nėra.</p>:students.map(student=><div className={'student-row '+(!student.active?'inactive':'')} key={student.id}><span className="avatar">{student.name[0].toUpperCase()}</span><div className="student-details"><strong>{student.name}{group==='remote'&&<span className="credit-count" title={`Iš viso panaudota taškų: ${student.credits_used||0}`}> ({progress(student.credits_used)}/4)</span>}</strong><span>{student.username||'Reikia nustatyti prisijungimą'}{!student.active?' · Išjungta':''}</span>{student.email&&<span>{student.email}</span>}<div className="row-actions"><button onClick={()=>{setEdit(student);setError('');}}>{student.username?'Redaguoti':'Nustatyti prisijungimą'}</button>{student.email&&<a href={'mailto:'+student.email}>Parašyti</a>}<button disabled={busy} style={{color:'#9b3434',borderColor:'#d9aaaa'}} onClick={async()=>{if(!window.confirm(`Ištrinti mokinį „${student.name}“? Bus pašalintas prisijungimas, jo pokalbiai ir privatūs failai. Šio veiksmo atšaukti negalima.`))return;setBusy(true);setError('');try{await api('students/'+student.id,'DELETE');if(edit?.id===student.id)setEdit(null);if(access?.name===student.name)setAccess(null);await refresh();report('Mokinys ištrintas.');}catch(e:any){setError(e.message);}finally{setBusy(false);}}}>Ištrinti</button></div></div></div>)}</section>
 {access&&<Modal title="Mokinio prisijungimas" close={()=>setAccess(null)}><h2>{access.name}</h2><p className="muted">Prisijungimas paruoštas.</p><div className="access-details"><p>Prisijungimo vardas <strong>{access.username}</strong></p><p>Slaptažodis <strong>{access.password}</strong></p></div><button className="button primary full" onClick={async()=>{try{await navigator.clipboard.writeText(accessText);setCopied(true);}catch{setCopied(false);}}}><Copy size={18}/>{copied?'Nukopijuota':'Kopijuoti prisijungimą'}</button>{access.email&&<a className="button glass-button full code-email" href={'mailto:'+access.email+'?subject='+encodeURIComponent('Matematika be streso – prisijungimas')+'&body='+encodeURIComponent(accessText)}><Mail size={18}/>Paruošti laišką</a>}<p className="hint">Slaptažodis rodomas tik dabar.</p></Modal>}
 </div>;
}
const largeReplyVideo=(file:File)=>file.size>25*1024*1024&&(file.type.startsWith('video/')||/\.(mp4|mov|webm)$/i.test(file.name));
async function uploadReplyVideo(file:File,task:string,student:string){
 const {id}=await api('reply-video','POST',{task,student,size:file.size});
 for(let offset=0;offset<file.size;){
  const chunk=file.slice(offset,offset+4*1024*1024);
  const response=await fetch('/api/reply-video/'+id,{method:'POST',headers:{'X-Video-Offset':String(offset)},body:chunk});
  const result=await response.json();
  if(!response.ok)throw new Error(result.error||'Nepavyko įkelti vaizdo įrašo.');
  if(result.offset!==offset+chunk.size)throw new Error('Nepavyko įkelti viso vaizdo įrašo. Pabandyk dar kartą.');
  offset=result.offset;
 }
 return id;
}
function FilePicker({files,setFiles,teacher=false}:{files:File[];setFiles:(f:File[])=>void;teacher?:boolean}){const [urls,setUrls]=useState<string[]>([]),[error,setError]=useState('');useEffect(()=>{const u=files.map(f=>URL.createObjectURL(f));setUrls(u);return()=>u.forEach(URL.revokeObjectURL);},[files]);function add(list:FileList|null){if(!list)return;const next=[...files,...Array.from(list)];if(next.length>5){setError('Galima pridėti iki 5 failų.');return;}if(teacher&&next.some(f=>largeReplyVideo(f)&&f.size>200*1024*1024)){setError('Vaizdo įrašas gali būti iki 200 MB.');return;}const regular=teacher?next.filter(f=>!largeReplyVideo(f)):next;if(regular.reduce((n,f)=>n+f.size,0)>25*1024*1024){setError('Bendras failų dydis turi būti iki 25 MB.');return;}if(regular.some(f=>f.size>(teacher?25:10)*1024*1024)){setError(teacher?'Vienas failas gali būti iki 25 MB.':'Viena nuotrauka gali būti iki 10 MB.');return;}if(next.some(f=>/heic|heif/i.test(f.type+f.name))){setError('HEIC nuotrauką išsaugok kaip JPG ir įkelk dar kartą.');return;}setError('');setFiles(next);}
return <div className="file-picker"><div className="upload-actions"><label className="button glass-button file-button"><Camera size={16}/>Fotografuoti<input type="file" accept="image/*" capture="environment" onChange={e=>{add(e.target.files);e.target.value='';}}/></label><label className="button glass-button file-button"><Upload size={16}/>{teacher?'Pridėti failą':'Įkelti nuotrauką'}<input type="file" accept={teacher?'image/*,audio/*,video/mp4,video/quicktime,video/webm,.mov':'image/*'} multiple onChange={e=>{add(e.target.files);e.target.value='';}}/></label></div>{!!files.length&&<div className="attachment-previews">{files.map((f,i)=><div className="attachment-preview" key={urls[i]||i}>{f.type.startsWith('image/')?<img src={urls[i]} alt={f.name}/>:<div className="media-icon">{f.type.startsWith('audio/')?<Mic/>:<Video/>}</div>}<span>{f.name}</span><button type="button" className="icon remove-file" aria-label={'Pašalinti '+f.name} onClick={()=>setFiles(files.filter((_,j)=>j!==i))}><X size={14}/></button></div>)}</div>}{error&&<p className="error" role="alert">{error}</p>}<p className="hint">Iki 5 failų. {teacher?'Vaizdo įrašas iki 200 MB. Kiti failai kartu iki 25 MB.':'JPG, PNG, WebP, GIF · iki 10 MB nuotraukai.'}</p></div>;
}
function TaskComposer({students,cancel,done,question=false,remoteHelp=false}:{remoteHelp?:boolean;question?:boolean;students:Student[];cancel:()=>void;done:(r:any)=>void}){
 const active=students.filter(s=>s.active);const [files,setFiles]=useState<File[]>([]),[selected,setSelected]=useState<string[]>([]),[helpType,setHelpType]=useState('homework'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function submit(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setError('');if(!question&&!selected.length){setError('Pasirink mokinį.');return;}const f=new FormData(e.currentTarget);if(remoteHelp)f.set('help_type',helpType);selected.forEach(id=>f.append('students',id));files.forEach(file=>f.append('files',file));setBusy(true);try{done(await api(question?'questions':'tasks','POST',f));}catch(e:any){setError(e.message);}finally{setBusy(false);}}
 return <form onSubmit={submit} className="composer"><div className="composer-heading"><h2>{question?(remoteHelp?'Nauja užklausa':'Paklausk mokytojo'):'Nauja užduotis'}</h2><button type="button" className="button subtle" onClick={cancel}>Atšaukti</button></div>{remoteHelp&&<div className="help-type-options" aria-label="Pagalbos tipas">{[['homework','Namų darbai','1 taškas'],['topic','Nauja tema','2 taškai']].map(([value,label,cost])=><label className={'help-type '+(helpType===value?'selected':'')} key={value}><input type="radio" name="help_type" value={value} checked={helpType===value} onChange={()=>setHelpType(value)}/><span><strong>{label}</strong><small>{cost}</small></span></label>)}</div>}<div className={'composer-layout '+(question?'question-composer':'')}><section className="glass panel"><label>Pavadinimas<input name="title" maxLength={120} placeholder="Pvz., Trupmenos"/></label><label>{question?'Kas neaišku?':'Užduotis'}<textarea name="body" rows={5} maxLength={5000} placeholder={question?"Parašyk, kuri vieta neaiški ir ką jau bandei…":"Parašyk arba pridėk nuotrauką…"}/></label><FilePicker files={files} setFiles={setFiles}/></section><section className="glass panel recipients">{question?<><h3>{remoteHelp&&helpType==='topic'?'Paaiškinsiu temą':'Padėsiu išsiaiškinti'}</h3><p className="muted">{remoteHelp?'Atsakymą gausi vaizdo įrašu.':'Atsiųsk užduotį ir savo klausimą.'}</p>{remoteHelp&&<p className="hint">Papildomai klausk tame pačiame pokalbyje – taškai nesikeis.</p>}</>:<><h3>Kam skirti?</h3>{!active.length?<p className="muted">Pirmiausia pridėk mokinį.</p>:<><label className="checkbox all"><input type="checkbox" checked={selected.length===active.length} onChange={e=>setSelected(e.target.checked?active.map(s=>s.id):[])}/>Visiems</label><div className="recipient-list">{active.map(student=><label className={'checkbox '+(selected.includes(student.id)?'checked':'')} key={student.id}><input type="checkbox" checked={selected.includes(student.id)} onChange={e=>setSelected(e.target.checked?[...selected,student.id]:selected.filter(id=>id!==student.id))}/>{student.name}</label>)}</div></>}</>}{error&&<p className="error" role="alert">{error}</p>}<button className="button primary full" disabled={busy||(!question&&!selected.length)}>{busy?<Loader2 className="spin" size={18}/>:<Send size={18}/>}Siųsti</button></section></div></form>;
}
function StudentPhoto({file,src,attach}:{file:Media;src:string;attach:(file:File)=>void}){
 const dialog=useRef<HTMLDialogElement>(null);
 const [rotation,setRotation]=useState(0);
 const [zoom,setZoom]=useState(1);
 const [ratio,setRatio]=useState(1);
 const picture=useRef<HTMLImageElement>(null);
 const ink=useRef<HTMLCanvasElement>(null);
 const [pen,setPen]=useState('');
 const [problem,setProblem]=useState('');
 const strokes=useRef<{color:string;points:{x:number;y:number}[]}[]>([]);
 const activePointer=useRef<number|null>(null);
 function redraw(){
  const canvas=ink.current,ctx=canvas?.getContext('2d');
  if(!canvas||!ctx)return;
  ctx.clearRect(0,0,canvas.width,canvas.height);
  ctx.lineWidth=Math.max(canvas.width,canvas.height)/350;
  ctx.lineCap='round';ctx.lineJoin='round';
  for(const {color,points} of strokes.current){
   ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(points[0].x-.01,points[0].y);
   for(const p of points)ctx.lineTo(p.x,p.y);
   ctx.stroke();
  }
 }
 function draw(event:React.PointerEvent<HTMLCanvasElement>,start:boolean){
  if(!pen||!event.isPrimary)return;
  const canvas=event.currentTarget,rect=canvas.getBoundingClientRect();
  if(start){activePointer.current=event.pointerId;canvas.setPointerCapture(event.pointerId);strokes.current.push({color:pen,points:[]});}
  if(activePointer.current!==event.pointerId)return;
  const x=(event.clientX-rect.left)/rect.width,y=(event.clientY-rect.top)/rect.height;
  const [a,b]=rotation===90?[y,1-x]:rotation===180?[1-x,1-y]:rotation===270?[1-y,x]:[x,y];
  strokes.current[strokes.current.length-1].points.push({x:a*canvas.width,y:b*canvas.height});redraw();
 }
 async function save(){
  try{
   const source=picture.current,overlay=ink.current;
   if(!source?.naturalWidth||!overlay||!strokes.current.length)throw new Error('Pirmiausia pažymėk nuotrauką.');
   const copy=document.createElement('canvas');
   copy.width=sideways?overlay.height:overlay.width;copy.height=sideways?overlay.width:overlay.height;
   const ctx=copy.getContext('2d');if(!ctx)throw new Error('Nepavyko paruošti nuotraukos.');
   ctx.fillStyle='white';ctx.fillRect(0,0,copy.width,copy.height);
   ctx.translate(copy.width/2,copy.height/2);ctx.rotate(rotation*Math.PI/180);
   for(const layer of [source,overlay])ctx.drawImage(layer,-overlay.width/2,-overlay.height/2,overlay.width,overlay.height);
   const blob=await new Promise<Blob|null>(resolve=>copy.toBlob(resolve,'image/jpeg',.93));
   if(!blob)throw new Error('Nepavyko išsaugoti nuotraukos.');
   attach(new File([blob],'Pazymetas-sprendimas.jpg',{type:'image/jpeg'}));dialog.current?.close();
  }catch(error){setProblem(error instanceof Error?error.message:'Nepavyko pridėti nuotraukos.');}
 }
 const sideways=rotation%180!==0;
 const displayRatio=sideways?1/ratio:ratio;
 function open(){
  setRotation(0);
  setZoom(1);
  dialog.current?.showModal();
 }
 return <>
  <button type="button" className="photo-view-trigger" onClick={open} aria-label={'Padidinti nuotrauką: '+file.name}>
   <img src={src} alt={file.name} loading="lazy"/>
  </button>
  <dialog ref={dialog} className="student-photo-dialog" aria-label="Mokinio nuotrauka">
   <div className="student-photo-toolbar">
    <button type="button" onClick={()=>setRotation(value=>(value+270)%360)}>↶ Pasukti kairėn</button>
    <button type="button" onClick={()=>setRotation(value=>(value+90)%360)}>↷ Pasukti dešinėn</button>
    <button type="button" aria-label="Sumažinti" disabled={zoom<=1} onClick={()=>setZoom(value=>value/1.5)}>−</button>
    <button type="button" aria-label="Pritaikyti prie ekrano" onClick={()=>setZoom(1)}>{Math.round(zoom*100)} %</button>
    <button type="button" aria-label="Padidinti" disabled={zoom>=5} onClick={()=>setZoom(value=>value*1.5)}>+</button>
    <button type="button" onClick={()=>dialog.current?.close()}>Uždaryti</button>
   </div>
   <div className="student-photo-toolbar">
    <button type="button" aria-pressed={!pen} onClick={()=>setPen('')}>Slinkti</button>
    {Object.entries({'Raudona':'#dc2626','Mėlyna':'#2563eb','Žalia':'#16803c','Oranžinė':'#dc7500'}).map(([label,color])=><button type="button" title={label} aria-label={label} aria-pressed={pen===color} key={color} onClick={()=>setPen(color)}><span style={{color}}>●</span></button>)}
    <button type="button" onClick={()=>{strokes.current.pop();redraw();}}>Atšaukti brūkšnį</button>
    <button type="button" onClick={save}>Pridėti prie atsakymo</button>
    {problem&&<span role="alert">{problem}</span>}
   </div>
   <div className="student-photo-scroll" tabIndex={0} aria-label="Nuotraukos peržiūra">
    <div className="student-photo-frame" style={{width:`min(${zoom*100}cqw, ${zoom*100*displayRatio}cqh)`,aspectRatio:displayRatio}}>
     <img ref={picture} src={src} alt={file.name} loading="lazy" onLoad={event=>{
      const {naturalWidth,naturalHeight}=event.currentTarget;
      if(naturalHeight){setRatio(naturalWidth/naturalHeight);const canvas=ink.current;if(canvas){const scale=Math.min(1,3200/Math.max(naturalWidth,naturalHeight));canvas.width=Math.max(1,Math.round(naturalWidth*scale));canvas.height=Math.max(1,Math.round(naturalHeight*scale));redraw();}}
     }} style={{width:sideways?`${100/displayRatio}%`:'100%',transform:`translate(-50%, -50%) rotate(${rotation}deg)`}}/>
     <canvas ref={ink} aria-label="Žymėjimas pieštuku" style={{position:'absolute',top:'50%',left:'50%',width:sideways?`${100/displayRatio}%`:'100%',height:'auto',transform:`translate(-50%, -50%) rotate(${rotation}deg)`,pointerEvents:pen?'auto':'none',touchAction:'none',cursor:'crosshair'}} onPointerDown={e=>draw(e,true)} onPointerMove={e=>draw(e,false)} onLostPointerCapture={()=>{activePointer.current=null;}}/>
    </div>
   </div>
  </dialog>
 </>;
}
function Attachment({file,attach}:{file:Media;attach?:(file:File)=>void}){const src='/api/files/'+file.id;return <div className="saved-attachment">{file.mime.startsWith('image/')?attach?<StudentPhoto file={file} src={src} attach={attach}/>:<a href={src} target="_blank" rel="noreferrer"><img src={src} alt={file.name} loading="lazy"/></a>:file.mime.startsWith('audio/')?<audio controls src={src} preload="metadata"/>:<video controls src={src} preload="metadata" playsInline/>}<a className="attachment-name" href={src} target="_blank" rel="noreferrer">{file.name}<ArrowUpRight size={12}/></a></div>;}
function Thread({user,data,back,select,refresh}:{user:User;data:Detail;back:()=>void;select:(s:string)=>void;refresh:()=>void}){const [files,setFiles]=useState<File[]>([]),[body,setBody]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');function attachPhoto(photo:File){
 if(files.length>=5||files.filter(file=>!largeReplyVideo(file)).reduce((sum,file)=>sum+file.size,photo.size)>25*1024*1024)throw new Error('Atsakyme telpa iki 5 failų. Nuotraukų ir kitų ne vaizdo failų riba – 25 MB.');
 setFiles(current=>[...current,photo]);
 }const teacher=user.role==='teacher';const stagedVideos=useRef(new WeakMap<File,{task:string;student:string;id:string}>());const printRef=useRef<HTMLDivElement>(null);const [printing,setPrinting]=useState(false);async function printTask(){setPrinting(true);setError('');try{const images=Array.from(printRef.current?.querySelectorAll<HTMLImageElement>('img')||[]);await Promise.all(images.map(img=>img.decode()));
 for(const img of images.filter(img=>img.classList.contains('worksheet-image'))){
  // Lighten predominantly black monochrome screenshots for paper; keep originals untouched.
  try{const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const ctx=canvas.getContext('2d');if(!ctx)continue;ctx.drawImage(img,0,0,64,64);const pixels=ctx.getImageData(0,0,64,64).data;let dark=0,chroma=0,visible=0;
   for(let i=0;i<pixels.length;i+=4){if(pixels[i+3]<128)continue;visible++;const r=pixels[i],g=pixels[i+1],b=pixels[i+2];if((r+g+b)/3<65)dark++;chroma+=Math.max(r,g,b)-Math.min(r,g,b);}
   img.classList.toggle('worksheet-dark',visible>0&&dark/visible>.6&&chroma/visible<30);
  }catch{/* A readable original remains available if image inspection is unsupported. */}
 }
 window.print();}catch{setError('Nepavyko įkelti visų nuotraukų spausdinimui. Pabandyk dar kartą.');}finally{setPrinting(false);}}useEffect(()=>{setFiles([]);setBody('');setError('');},[data.studentId,data.task.id]);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);setError('');const f=new FormData();f.set('task',data.task.id);f.set('student',data.studentId);f.set('body',body);try{for(const file of files){if(teacher&&largeReplyVideo(file)){const task=data.task.id,student=data.studentId;let staged=stagedVideos.current.get(file);if(staged?.task!==task||staged.student!==student){staged={task,student,id:await uploadReplyVideo(file,task,student)};stagedVideos.current.set(file,staged);}f.append('video',staged.id);}else f.append('files',file);}await api('messages','POST',f);setFiles([]);setBody('');refresh();}catch(e:any){setError(e.message);}finally{setBusy(false);}}
return <div className="thread"><div className="task-printout" ref={printRef}>
 <div className="worksheet-header"><img className="worksheet-logo" src="/logo.webp" alt="Matematika be streso"/><div><strong>MATEMATIKOS UŽDUOTIS</strong><span>matematikabestreso.lt</span></div></div>
 <div className="worksheet-title"><span>SAVARANKIŠKAS DARBAS</span><h1>{data.task.title}</h1></div>
 <div className="worksheet-student"><span>Vardas, pavardė <i/></span><span>Data <i/></span></div>
 {data.task.body&&<p className="worksheet-instructions">{data.task.body}</p>}
 <div className="worksheet-images">{data.files.filter(f=>!f.message_id&&f.mime.startsWith('image/')).map(f=><figure key={f.id}><img className="worksheet-image" src={'/api/files/'+f.id} alt="Užduoties nuotrauka"/></figure>)}</div>
 <div className="worksheet-solution"><h2>Sprendimas</h2><div/><div/><div/><div/></div>
 <div className="worksheet-footer"><strong>Matematika be streso</strong><span>matematikabestreso.lt</span></div>
 </div><button className="back-link" onClick={back}><ArrowLeft size={15}/>{inquiry(data.task)?'Visi klausimai':'Visos užduotys'}</button><button className="button glass-button print-task-button" onClick={printTask} disabled={printing}><Printer size={19}/>{printing?'Ruošiama…':'Spausdinti užduotį'}</button><div className="thread-heading"><div><span className="eyebrow">{date(data.task.created)}</span><h2>{data.task.title}</h2></div>{teacher&&<label className="student-select">Mokinio atsakymai<select value={data.studentId} onChange={e=>select(e.target.value)}>{data.students.map(s=><option value={s.id} key={s.id}>{s.name}{s.replies?' · atsakė':''}</option>)}</select></label>}</div><div className="thread-layout"><section className="glass panel task-detail"><h3>{inquiry(data.task)?kindLabel(data.task):'Užduotis'}</h3>{data.task.body&&<p className="pre-wrap">{data.task.body}</p>}{data.files.filter(f=>!f.message_id).map(f=><Attachment file={f} key={f.id} attach={teacher&&inquiry(data.task)?attachPhoto:undefined}/>)}<div className="private-note"><LockKeyhole size={13}/>Sprendimus mato tik mokinys ir mokytojas.</div></section><section className="discussion"><div className="message-stream" aria-live="polite">{!data.messages.length&&<div className="message-empty"><FileText size={20}/><p>{inquiry(data.task)?(teacher?'Pridėk savo atsakymą.':'Atsakymą rasi čia.'):(teacher?'Mokinys dar nepateikė sprendimo. Gali parašyti jam pirmas.':'Sprendimą užrašyk ant popieriaus, nufotografuok ir atsiųsk čia.')}</p></div>}{data.messages.map(m=><article className={'message glass '+(m.author==='teacher'?'from-teacher':'')} key={m.id}><div className="message-meta"><strong>{m.author==='teacher'?'Mokytojas':teacher?data.students.find(s=>s.id===data.studentId)?.name:'Tu'}</strong><time>{date(m.created)} · {new Date(m.created).toLocaleTimeString('lt-LT',{hour:'2-digit',minute:'2-digit'})}</time></div>{m.author!=='teacher'&&m.body&&<p className="pre-wrap">{m.body}</p>}{data.files.filter(f=>f.message_id===m.id).map(f=><Attachment key={f.id} file={f} attach={teacher&&m.author==='student'?attachPhoto:undefined}/>)}{m.author==='teacher'&&m.body&&<p className="pre-wrap">{m.body}</p>}</article>)}</div><form className="glass panel reply-composer" onSubmit={submit}><h3>{teacher?'Atsakymas':'Tavo žinutė'}</h3><label className="sr-only" htmlFor="reply">Komentaras</label><textarea id="reply" value={body} onChange={e=>setBody(e.target.value)} maxLength={5000} rows={3} placeholder={teacher?'Paaiškink, padrąsink arba pridėk įrašą…':'Komentaras (nebūtina)'}/><FilePicker files={files} setFiles={setFiles} teacher={teacher}/>{teacher&&<Recorder add={f=>setFiles(prev=>[...prev,f].slice(0,5))}/>}<div className="reply-bottom"><span className="hint">{teacher?'Tekstas, nuotrauka, balso ar vaizdo įrašas.':'Galima pridėti kelias sprendimo nuotraukas.'}</span><button className="button primary" disabled={busy||(!body.trim()&&!files.length)}>{busy?<Loader2 className="spin" size={15}/>:<Send size={15}/>} Siųsti</button></div>{error&&<p className="error" role="alert">{error}</p>}</form></section></div></div>;
}
function Recorder({add}:{add:(f:File)=>void}){const [recording,setRecording]=useState<string|null>(null),[error,setError]=useState('');const recorder=useRef<MediaRecorder|null>(null),stream=useRef<MediaStream|null>(null),timer=useRef<ReturnType<typeof setTimeout>|null>(null),preview=useRef<HTMLVideoElement>(null);function stop(){if(recorder.current?.state==='recording')recorder.current.stop();if(timer.current)clearTimeout(timer.current);}useEffect(()=>()=>{if(timer.current)clearTimeout(timer.current);if(recorder.current?.state==='recording'){recorder.current.onstop=null;recorder.current.stop();}stream.current?.getTracks().forEach(t=>t.stop());},[]);async function start(video:boolean){setError('');if(!navigator.mediaDevices||!window.MediaRecorder){setError('Ši naršyklė nepalaiko įrašymo. Įrašyk telefonu ir pridėk failą.');return;}try{const s=await navigator.mediaDevices.getUserMedia({audio:true,video:video?{width:640,height:480}:false});stream.current=s;const mime=(video?['video/webm','video/mp4']:['audio/webm','audio/mp4']).find(t=>MediaRecorder.isTypeSupported(t));const r=new MediaRecorder(s,mime?{mimeType:mime}:undefined);recorder.current=r;const chunks:BlobPart[]=[];r.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};r.onstop=()=>{s.getTracks().forEach(t=>t.stop());if(timer.current)clearTimeout(timer.current);const type=r.mimeType.split(';')[0],b=new Blob(chunks,{type});if(b.size>(video?200:25)*1024*1024)setError('Įrašas per didelis. Pabandyk trumpesnį.');else add(new File([b],`${video?'paaiskinimas':'balso-zinute'}-${Date.now()}.${type.includes('mp4')?'mp4':'webm'}`,{type}));setRecording(null);};r.start();setRecording(video?'video':'audio');timer.current=setTimeout(stop,video?60000:120000);if(video)setTimeout(()=>{if(preview.current){preview.current.srcObject=s;preview.current.play().catch(()=>{});}},50);}catch{stream.current?.getTracks().forEach(t=>t.stop());setError('Nepavyko įjungti kameros ar mikrofono. Patikrink leidimus arba pridėk jau įrašytą failą.');}}
return <div className="recorder">{recording?<><div className="recording"><span className="recording-dot"/>Įrašoma {recording==='video'?'iki 1 min.':'iki 2 min.'}<button type="button" className="button subtle" onClick={stop}><Square size={13} fill="currentColor"/>Baigti įrašą</button></div>{recording==='video'&&<video ref={preview} muted playsInline className="recording-preview"/>}</>:<div className="upload-actions"><button type="button" className="button subtle" onClick={()=>start(false)}><Mic size={16}/>Įrašyti balsą</button><button type="button" className="button subtle" onClick={()=>start(true)}><Video size={16}/>Įrašyti vaizdą</button></div>}{error&&<p className="error" role="alert">{error}</p>}</div>;
}
